<section class="section page-top"><div class="container portal-layout"><?php require ROOT_PATH.'/app/Views/client/_nav.php'; ?><div><h1>Dashboard Client</h1><div class="summary-grid"><?php if(!$projects): ?><article class="metric"><span>Project Aktif</span><strong>0</strong><small>Belum ada project aktif.</small></article><?php else: ?><?php foreach($projects as $p): ?><article class="metric"><span><?= e($p['project_no']) ?></span><strong><?= e($p['progress_percent']) ?>%</strong><small><?= e($p['title']) ?> • <?= e($p['status']) ?></small></article><?php endforeach; ?><?php endif; ?></div><h2>Estimasi Terbaru</h2><div class="table-wrap"><table><tr><th>Jenis</th><th>Status</th><th>Tanggal</th></tr><?php foreach($estimates as $r): ?><tr><td><?= e($r['job_type']) ?></td><td><?= e($r['status']) ?></td><td><?= e($r['created_at']) ?></td></tr><?php endforeach; ?></table></div><h2>Survey</h2><div class="table-wrap"><table><tr><th>Jenis</th><th>Status</th><th>Tanggal Pilihan</th></tr><?php foreach($surveys as $r): ?><tr><td><?= e($r['job_type']) ?></td><td><?= e($r['status']) ?></td><td><?= e($r['preferred_date']) ?></td></tr><?php endforeach; ?></table></div></div></div></section>